   }
   if (!isset($this->NM_cmp_hidden['consecutivo']) || $this->NM_cmp_hidden['consecutivo'] != "off") { 
   $nm_saida->saida("     <TD class=\"" . $this->css_inherit_bg . ' ' . $this->css_scGridLabelFont . $this->css_sep . $this->css_consecutivo_label . "\"  style=\"" . $this->css_scGridLabelNowrap . "" . $this->Css_Cmp['css_consecutivo_label'] . "\" >\r\n");
